    return (None, None, None, None)

def bareiss(mat, cumm=1, depth=0):
    prefix = '  ' * depth
    print(f'{prefix}bareiss called with cumm={cumm}')
    print(f'{prefix}mat = {mat.tolist()}')

    if mat.rows == 0:
        return S.One
    elif mat.rows == 1:
        return mat[0, 0]

    col = mat[:, 0]
    print(f'{prefix}first column: {list(col)}')

    pivot_pos, pivot_val, _, _ = _find_pivot(col)
    print(f'{prefix}pivot_pos={pivot_pos}, pivot_val={pivot_val}')

    if pivot_pos is None:
        return S.Zero

    sign = (-1) ** (pivot_pos % 2)
    rows = list(i for i in range(mat.rows) if i != pivot_pos)
    cols = list(range(mat.cols))
    tmp_mat = mat.extract(rows, cols)

    def entry(i, j):
        ret = (pivot_val*tmp_mat[i, j + 1] - mat[pivot_pos, j + 1]*tmp_mat[i, 0]) / cumm
        if not ret.is_Atom:
            cancel(ret)  # Note: result not assigned!
        return ret

    new_mat = Matrix(mat.rows - 1, mat.cols - 1, entry)
    return sign * bareiss(new_mat, pivot_val, depth + 1)

